    95|/**
    96| * Mark the primary provider as failed after a confirmed auth error (401/403).
    97| * Once marked failed, subsequent requests skip the primary and go directly
    98| * to fallback (if configured) or return AI_UNAVAILABLE.
    99| */
   100|export function markProviderFailed(httpStatus: number, error: string, traceId: string): void {
   101|  state.state = 'PROVIDER_FAILED';
   102|  failureLatchedAtMs = Date.now();
   103|  state.credentialValid = false;
   104|  state.lastHttpStatus = httpStatus;
   105|  state.lastValidationTime = nowIso();
   106|  state.traceId = traceId;
   107|  state.error = error;
   108|  console.error('[IVXProviderStateMachine] PROVIDER_FAILED', {
   109|    provider: state.provider,
   110|    httpStatus,
   111|    traceId,
   112|    error: error.slice(0, 200),
   113|  });
   114|}
   115|
   116|/**
   117| * Mark the primary provider as ready after a successful request.
   118| */
   119|export function markProviderReady(provider: string, model: string): void {
   120|  state.state = 'PROVIDER_READY';
   121|  failureLatchedAtMs = null;
   122|  state.provider = provider;
   123|  state.model = model;
   124|  state.credentialLoaded = true;
   125|  state.credentialValid = true;
   126|  state.lastValidationTime = nowIso();
   127|  state.lastHttpStatus = 200;
   128|  state.adapterVersion = getAdapterVersion();
   129|  state.error = null;
   130|}
   131|
   132|/**
   133| * Mark fallback as used and ready.
   134| */
   135|export function markFallbackReady(provider: string, model: string): void {
   136|  state.state = 'FALLBACK_READY';
   137|  failureLatchedAtMs = null;
   138|  state.fallbackUsed = true;
   139|  state.fallbackEnabled = true;
   140|  state.lastHttpStatus = 200;
   141|  state.lastValidationTime = nowIso();
   142|  console.log('[IVXProviderStateMachine] FALLBACK_READY', { provider, model });
   143|}
   144|
   145|/**
   146| * Mark AI as completely unavailable — primary failed, no fallback succeeded.
   147| */
   148|export function markAIUnavailable(traceId: string, error: string): void {
   149|  state.state = 'AI_UNAVAILABLE';
   150|  failureLatchedAtMs = Date.now();
   151|  state.traceId = traceId;
   152|  state.error = error;
   153|  state.lastValidationTime = nowIso();
   154|  console.error('[IVXProviderStateMachine] AI_UNAVAILABLE', { traceId, error: error.slice(0, 200) });
   155|}
   156|
   157|/**
   158| * Initialize the state machine at startup with the detected provider info.
   159| */
   160|export function initProviderStateMachine(provider: string, model: string, credentialLoaded: boolean, fallbackEnabled: boolean): void {
   161|  state.provider = provider;
   162|  state.model = model;
   163|  state.credentialLoaded = credentialLoaded;
   164|  state.fallbackEnabled = fallbackEnabled;
   165|  state.adapterVersion = getAdapterVersion();
   166|  state.state = credentialLoaded ? 'PROVIDER_VALIDATING' : 'AI_UNAVAILABLE';
   167|  state.lastValidationTime = nowIso();
   168|}
   169|
   170|/**
   171| * Returns true if the primary provider should be attempted.
   172| *
   173| * Failure states (PROVIDER_FAILED / AI_UNAVAILABLE) block the primary only
   174| * for the recovery cooldown window. After the cooldown, the circuit re-opens
   175| * half-way: the state moves back to PROVIDER_VALIDATING and exactly one probe
   176| * attempt is allowed. Success re-latches PROVIDER_READY; failure re-latches
   177| * the failure state and restarts the cooldown. Recovery is only offered when
   178| * a credential is actually loaded.
   179| */
   180|export function shouldTryPrimary(): boolean {
   181|  if (state.state !== 'PROVIDER_FAILED' && state.state !== 'AI_UNAVAILABLE') {
   182|    return true;
   183|  }
   184|  if (!state.credentialLoaded) {
   185|    return false;
   186|  }
   187|  if (failureLatchedAtMs !== null && Date.now() - failureLatchedAtMs >= RECOVERY_COOLDOWN_MS) {
   188|    state.state = 'PROVIDER_VALIDATING';
   189|    failureLatchedAtMs = null;
   190|    console.log('[IVXProviderStateMachine] Recovery cooldown elapsed — re-opening primary provider for a half-open probe attempt', {
   191|      cooldownMs: RECOVERY_COOLDOWN_MS,
   192|    });
   193|    return true;
   194|  }
   195|  return false;
   196|}
   197|
   198|/**
   199| * Returns true if a fallback should be attempted.
   200| * Only if fallback is enabled AND the primary just failed (not if already unavailable).
   201| */
   202|export function shouldTryFallback(): boolean {
   203|  return state.state === 'PROVIDER_FAILED';
   204|}
